#include <iostream>
#include <algorithm>
#include <memory>

class Discount {
public:
    virtual ~Discount() = default;
    virtual double apply(double price) const = 0;
};

class PercentageDiscount : public Discount {
public:
    explicit PercentageDiscount(double percent) : percent_(percent) {}
    double apply(double price) const override { return price - (price * percent_) / 100; }

private:
    double percent_;
};

class FlatDiscount : public Discount {
public:
    explicit FlatDiscount(double amount) : amount_(amount) {}
    double apply(double price) const override { return std::max(0.0, price - amount_); }

private:
    double amount_;
};

int main() {
    std::unique_ptr<Discount> percentage = std::make_unique<PercentageDiscount>(10);
    std::unique_ptr<Discount> flat = std::make_unique<FlatDiscount>(20);
    std::cout << percentage->apply(200) << std::endl; // 180
    std::cout << flat->apply(200) << std::endl;        // 180
    return 0;
}

